public boolean wordBreak(String s, List<String> wordDict) {
    Set<String> words = new HashSet<>(wordDict);
    Boolean[] memo = new Boolean[s.length() + 1];
    return canBreak(s, 0, words, memo);
}

private boolean canBreak(String s, int start, Set<String> words, Boolean[] memo) {
    if (start == s.length()) {
        return true;
    }
    if (memo[start] != null) {
        return memo[start];
    }
    for (int end = start + 1; end <= s.length(); end++) {
        if (words.contains(s.substring(start, end)) && canBreak(s, end, words, memo)) {
            memo[start] = true;
            return true;
        }
    }
    memo[start] = false;
    return false;
}

